impl SseEncode for crate::api::hub::HubSubscriptionEvent {
    // Codec=Sse (Serialization based), see doc to use other codecs
    fn sse_encode(self, serializer: &mut flutter_rust_bridge::for_generated::SseSerializer) {
        match self {
            crate::api::hub::HubSubscriptionEvent::Connected { subscription_id } => {
                <i32>::sse_encode(0, serializer);
                <String>::sse_encode(subscription_id, serializer);
            }
            crate::api::hub::HubSubscriptionEvent::MessageReceived {
                subscription_id,
                event_name,
                payload_json,
            } => {
                <i32>::sse_encode(1, serializer);
                <String>::sse_encode(subscription_id, serializer);
                <String>::sse_encode(event_name, serializer);
                <String>::sse_encode(payload_json, serializer);
            }
            crate::api::hub::HubSubscriptionEvent::Disconnected {
                subscription_id,
                reason,
            } => {
                <i32>::sse_encode(2, serializer);
                <String>::sse_encode(subscription_id, serializer);
                <String>::sse_encode(reason, serializer);
            }
            crate::api::hub::HubSubscriptionEvent::Stopped { subscription_id } => {
                <i32>::sse_encode(3, serializer);
                <String>::sse_encode(subscription_id, serializer);
            }
            crate::api::hub::HubSubscriptionEvent::Failed {
                subscription_id,
                error,
            } => {
                <i32>::sse_encode(4, serializer);
                <String>::sse_encode(subscription_id, serializer);
                <String>::sse_encode(error, serializer);
            }
            _ => {
                unimplemented!("");
            }
        }
    }
}

